import{_ as s,C as t,o as r,c as o,E as i,a2 as c}from"./chunks/framework.BOeh4kYD.js";const d="/joinwell52/assets/verification-evidence-20260909/verification-ownership-figure.en.svg",v=JSON.parse('{"title":"The Verification Claim Was Denied. Why Was Its Completion Still Attempted?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Verification Claim Was Denied. Why Was Its Completion Still Attempted?","date":"2026-09-09","published_date":"2026-09-09","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","edition":"research-center","research_question":"The Verification Claim Was Denied. Why Was Its Completion Still Attempted?","summary":"Six experiments against an upstream verification tool separate request identity, execution, and the authority to finish a request.","cover":"/assets/verification-evidence-20260909/02-verification-ownership.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments; not independent QA; dependency substitutions disclosed","pageClass":"verification-evidence-article","sources":["https://github.com/Runfusion/Fusion/pull/3590"]},"headers":[],"relativePath":"en/engineering/2026-09-09-verification-ownership.md","filePath":"en/engineering/2026-09-09-verification-ownership.md","lastUpdated":1788930481000}'),l={name:"en/engineering/2026-09-09-verification-ownership.md"};function h(u,e,p,m,g,f){const n=t("ArticleCover"),a=t("ArticleTableScroll");return r(),o("div",null,[i(n,{image:"/assets/verification-evidence-20260909/02-verification-ownership.png",kicker:"Engineering · Experimental research",title:"The Verification Claim Was Denied. Why Was Its Completion Still Attempted?",summary:"Six experiments against an upstream verification tool separate request identity, execution, and the authority to finish a request.",version:"2026-09-09",languageHref:"/zh/engineering/2026-09-09-verification-ownership",languageLabel:"中文"}),i(a,{language:"en"}),e[0]||(e[0]=c('<h1 id="the-verification-claim-was-denied-why-was-its-completion-still-attempted" tabindex="-1">The Verification Claim Was Denied. Why Was Its Completion Still Attempted? <a class="header-anchor" href="#the-verification-claim-was-denied-why-was-its-completion-still-attempted" aria-label="Permalink to &quot;The Verification Claim Was Denied. Why Was Its Completion Still Attempted?&quot;">​</a></h1><p>A verification request is already running. Another executor receives its ID, together with a negative claim result. Two questions follow: can the second executor continue running its own command, and can it attach that result to the first request?</p><p>Our isolated experiment observed the second behavior at a tool boundary: the unclaimed branch executed the current command and invoked the completion callback with the existing request ID. Persistence was a fixture, so this does not establish an actual database update.</p><h2 id="persistence-makes-the-question-possible" tabindex="-1">Persistence makes the question possible <a class="header-anchor" href="#persistence-makes-the-question-possible" aria-label="Permalink to &quot;Persistence makes the question possible&quot;">​</a></h2><p>Fusion is an open-source project for organizing agent development work. <a href="https://github.com/Runfusion/Fusion/pull/3590" target="_blank" rel="noreferrer">PR #3590</a> proposes write-ahead verification records, bounded execution, and stale-running recovery. We inspected the still-unmerged commit <code>b5d75aba5e7cdc145921113a1b069db95fa781f7</code>.</p><p>A request must survive before a recovery process can inspect it. But its existence leaves another obligation: the stored work, executed command, and authorized completer must correspond.</p><p>Following the returned request ID exposed where that correspondence needs attention.</p><h2 id="one-identifier-several-responsibilities" tabindex="-1">One identifier, several responsibilities <a class="header-anchor" href="#one-identifier-several-responsibilities" aria-label="Permalink to &quot;One identifier, several responsibilities&quot;">​</a></h2><p>The tool saves <code>request.requestId</code> before handling <code>claimed=false</code>. That branch warns, but neither stops execution nor clears the saved ID. It then runs the current <code>effectiveCommand</code>. The completion helper checks that persistence and a nonempty ID exist before calling <code>finish</code>.</p><p>Allowing an untracked check to proceed may be a deliberate availability choice. Sending its outcome to a different in-flight request requires a separate justification.</p><p>The inspected storage completion function matches task, request ID, and running state. This identifies a database integration question; reading the condition does not test transaction isolation or concurrent ownership.</p><h2 id="six-experiments-through-the-original-tool" tabindex="-1">Six experiments through the original tool <a class="header-anchor" href="#six-experiments-through-the-original-tool" aria-label="Permalink to &quot;Six experiments through the original tool&quot;">​</a></h2><p>We loaded the complete upstream module, erased TypeScript types, and supplied explicit dependency seams. The actual <code>createRunVerificationTool().execute()</code> ran. Queue admission was immediate, persistence was controlled, and the sandbox seam executed a harmless <code>node --version</code> child process.</p><table tabindex="0"><thead><tr><th>Condition</th><th style="text-align:right;">Execute calls</th><th style="text-align:right;">Finish calls</th><th>Observation</th></tr></thead><tbody><tr><td>Fresh request</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Persist, execute, finish</td></tr><tr><td>Claimed response identifies another command&#39;s request</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Current command; existing request ID</td></tr><tr><td>Existing running request, claimed=false</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Completion still attempted</td></tr><tr><td>Upsert throws</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>Tool reports execution success</td></tr><tr><td>Runner throws</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Failed completion attempted, error rethrown</td></tr><tr><td>Finish throws</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>Tool still reports execution success</td></tr></tbody></table><p><img src="'+d+'" alt="Figure: schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence."></p><p><em>Figure 1. schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence.</em></p><p>Two independent process runs agreed. The runner-error control prevents an overstatement: ordinary failure settlement exists. The issue is how particular ownership and persistence failures constrain later callbacks.</p><p>A callback count measures an attempted operation. Our fixture accepting it is not proof that PostgreSQL accepted an incorrect update.</p><h2 id="execution-success-and-recorded-success" tabindex="-1">Execution success and recorded success <a class="header-anchor" href="#execution-success-and-recorded-success" aria-label="Permalink to &quot;Execution success and recorded success&quot;">​</a></h2><p>Continuing after write-ahead failure exposes a real design choice: should a useful check stop whenever recording is unavailable? Either answer needs an explicit contract. If execution continues, callers should distinguish “the command succeeded” from “its outcome is durably recorded.”</p><p>Likewise, failure to persist a successful result is not automatically a reason to rerun the command. Recovery may need to resubmit evidence, provided that evidence still belongs to the same work and authorized attempt.</p><p>Review three relationships: whether claim failure revokes completion authority; whether the claimed work matches the executed command; and whether execution and persistence outcomes remain independently visible.</p><p>Possible designs include rejecting incompatible claims, executing the claimed request&#39;s command, or creating a separate request. A completion capability or attempt identity may be appropriate, but this study does not freeze that interface.</p><p>These are upstream findings, not a demonstrated CodeFlowMu defect. We did not run Fusion&#39;s database, full queue, or startup recovery. The <a href="https://joinwell52-ai.github.io/joinwell52/en/research/evidence/2026-09-09-verification-evidence" target="_blank" rel="noreferrer">evidence guide</a> records exactly which dependencies were replaced.</p><p>Persisting a request lets a system remember that work exists. Checking completion authority lets it justify which later result belongs to that work.</p>',25))])}const x=s(l,[["render",h]]);export{v as __pageData,x as default};
